const upsertEntrySeason = `-- name: UpsertEntrySeason :exec
INSERT INTO entry_seasons (entry_id, season, status, score, notes) VALUES (?, ?, ?, ?, ?)
ON CONFLICT (entry_id, season) DO UPDATE SET status = excluded.status, score = excluded.score, notes = excluded.notes
`

type UpsertEntrySeasonParams struct {
	EntryID int64           `json:"entry_id"`
	Season  int64           `json:"season"`
	Status  string          `json:"status"`
	Score   sql.NullFloat64 `json:"score"`
	Notes   string          `json:"notes"`
}

func (q *Queries) UpsertEntrySeason(ctx context.Context, arg UpsertEntrySeasonParams) error {
	_, err := q.db.ExecContext(ctx, upsertEntrySeason,
		arg.EntryID,
		arg.Season,
		arg.Status,
		arg.Score,
		arg.Notes,
	)
	return err
}

const watchBounds = `-- name: WatchBounds :one
SELECT MIN(watched_at) AS first_at, MAX(watched_at) AS last_at
FROM watches WHERE entry_id = ? AND season > 0 AND source != 'assumed'
`

type WatchBoundsRow struct {
	FirstAt interface{} `json:"first_at"`
	LastAt  interface{} `json:"last_at"`
}

func (q *Queries) WatchBounds(ctx context.Context, entryID int64) (WatchBoundsRow, error) {
	row := q.db.QueryRowContext(ctx, watchBounds, entryID)
	var i WatchBoundsRow
	err := row.Scan(&i.FirstAt, &i.LastAt)
	return i, err
}
